const width = document.getElementById('viewport'),
  variant = document.getElementById('variant'),
  position = document.getElementById('position')
function update() {
  const w = Number(width.value),
    v = variant.value,
    rows = data.results.filter(r => r.viewport.width === w),
    base = rows.find(r => r.variant === 'baseline')
  document.getElementById('baseline').src = `${w}-baseline.png`
  document.getElementById('candidate').src = `${w}-${v}.png`
  document.getElementById('baselineLink').href = `${w}-baseline.png`
  document.getElementById('candidateLink').href = `${w}-${v}.png`
  document.getElementById('caption').textContent =
    variant.selectedOptions[0].textContent
  document.getElementById('measurements').innerHTML = rows
    .map(
      r =>
        `<tr><td>${r.variant}</td><td>${r.detailHeight} px</td><td>${base.detailHeight - r.detailHeight} px (${Math.round(((base.detailHeight - r.detailHeight) / base.detailHeight) * 100)}%)</td><td>${r.cardHeight} / ${r.suggestionsHeight} px</td></tr>`,
    )
    .join('')
}
width.addEventListener('change', update)
variant.addEventListener('change', update)
position.addEventListener('input', () => {
  document.getElementById('candidate').style.clipPath =
    `inset(0 0 0 ${position.value}%)`
  document.getElementById('divider').style.left = `${position.value}%`
})
document.getElementById('captureDate').textContent =
  `Captured ${data.capturedAt}.`
update()
